// [S4] Three-portal family features — My Doctor: Royal Blue Hero banner,
// current family doctor panel with VERIFIED badge, and directory search with district filter.
import 'package:family_veda/models/doctor_summary.dart';
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/theme/app_theme.dart';
import 'package:family_veda/widgets/shared/async_state_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

final doctorDistrictFilterProvider = StateProvider.autoDispose<String>((ref) => '');

class MyDoctorScreen extends ConsumerWidget {
  const MyDoctorScreen({super.key});

  Future<void> _request(BuildContext context, WidgetRef ref, String familyId, String doctorId, String doctorName) async {
    try {
      await ref.read(familyPortalApiProvider).requestFamilyDoctor(
        familyId: familyId,
        doctorId: doctorId,
      );
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Request sent to $doctorName.'),
            backgroundColor: AppColors.success,
          ),
        );
      }
    } on Object {
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not send the request. There may already be one pending.'),
            backgroundColor: AppColors.danger,
          ),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return Scaffold(
      backgroundColor: Colors.transparent,
      body: SafeArea(
        child: ref.watch(familyDashboardProvider).when(
          loading: () => const LoadingStateView(label: 'Loading family doctor'),
          error: (_, _) => ErrorRetryView(
            onRetry: () => ref.invalidate(familyDashboardProvider),
          ),
          data: (dashboard) {
            final familyId = dashboard.familyId;
            if (familyId == null) {
              return const EmptyStateView(
                title: 'No family found',
                message: 'Join or create a family first.',
              );
            }
            return _MyDoctorBody(
              familyId: familyId,
              isHead: dashboard.isHead,
              onRequest: _request,
            );
          },
        ),
      ),
    );
  }
}

class _MyDoctorBody extends ConsumerStatefulWidget {
  const _MyDoctorBody({
    required this.familyId,
    required this.isHead,
    required this.onRequest,
  });

  final String familyId;
  final bool isHead;
  final Future<void> Function(BuildContext, WidgetRef, String, String, String) onRequest;

  @override
  ConsumerState<_MyDoctorBody> createState() => _MyDoctorBodyState();
}

class _MyDoctorBodyState extends ConsumerState<_MyDoctorBody> {
  final _searchController = TextEditingController();
  final _districtController = TextEditingController();

  @override
  void dispose() {
    _searchController.dispose();
    _districtController.dispose();
    super.dispose();
  }

  void _onSearch() {
    ref.read(doctorDirectorySearchProvider.notifier).state = _searchController.text.trim();
    ref.read(doctorDistrictFilterProvider.notifier).state = _districtController.text.trim();
  }

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final primaryColor = isDark ? AppColors.primaryLumDark : AppColors.primary;

    return ListView(
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
      children: [
        // 1. Royal Blue Web Hero Banner
        Container(
          decoration: BoxDecoration(
            gradient: const LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: [
                Color(0xFF0F52BA), // Royal Blue
                Color(0xFF1D61E0),
                Color(0xFF2563EB), // Vibrant Web Blue
              ],
            ),
            borderRadius: BorderRadius.circular(20),
            boxShadow: [
              BoxShadow(
                color: const Color(0xFF1D61E0).withValues(alpha: 0.35),
                blurRadius: 18,
                offset: const Offset(0, 6),
              ),
            ],
          ),
          padding: const EdgeInsets.all(20),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'LONG-TERM CARE',
                style: TextStyle(
                  fontSize: 10.5,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 1.1,
                  color: Color(0xFFB9D5FD),
                ),
              ),
              const SizedBox(height: 6),
              const Text(
                'My Doctor',
                style: TextStyle(
                  fontSize: 22,
                  fontWeight: FontWeight.w700,
                  letterSpacing: -0.4,
                  color: Colors.white,
                ),
              ),
              const SizedBox(height: 6),
              Text(
                widget.isHead
                    ? "Your family's long-term doctor. Only you, as Family Head, can request or change the doctor."
                    : "Your family's doctor, chosen by the Family Head. Your records are shared only with your consent.",
                style: const TextStyle(
                  fontSize: 12.5,
                  height: 1.4,
                  color: Color(0xFFE0EDFE),
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 16),

        // 2. Current Family Doctor Panel
        Container(
          padding: const EdgeInsets.all(18),
          decoration: BoxDecoration(
            color: isDark ? const Color(0xFF1E293B) : Colors.white,
            borderRadius: BorderRadius.circular(18),
            border: Border.all(
              color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
            ),
            boxShadow: [
              BoxShadow(
                color: Colors.black.withValues(alpha: isDark ? 0.3 : 0.03),
                blurRadius: 12,
                offset: const Offset(0, 4),
              ),
            ],
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Current family doctor',
                style: TextStyle(
                  fontSize: 17.5,
                  fontWeight: FontWeight.w700,
                  color: isDark ? Colors.white : const Color(0xFF0F172A),
                ),
              ),
              const SizedBox(height: 12),
              ref.watch(familyDoctorProvider(widget.familyId)).when(
                    loading: () => const Padding(
                      padding: EdgeInsets.symmetric(vertical: 8),
                      child: LinearProgressIndicator(),
                    ),
                    error: (_, _) => Text(
                      'Could not load assigned doctor.',
                      style: TextStyle(color: isDark ? AppColors.mutedDark : AppColors.muted),
                    ),
                    data: (doctor) {
                      if (doctor == null) {
                        return Container(
                          padding: const EdgeInsets.all(14),
                          decoration: BoxDecoration(
                            color: isDark ? const Color(0xFF0F172A) : const Color(0xFFF8FAFC),
                            borderRadius: BorderRadius.circular(12),
                            border: Border.all(
                              color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
                            ),
                          ),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                'No family doctor yet',
                                style: TextStyle(
                                  fontWeight: FontWeight.w700,
                                  fontSize: 14,
                                  color: isDark ? Colors.white : const Color(0xFF0F172A),
                                ),
                              ),
                              const SizedBox(height: 3),
                              Text(
                                widget.isHead
                                    ? 'Search below and send a request to assign a trusted family doctor.'
                                    : 'The family head has not assigned a doctor yet.',
                                style: TextStyle(
                                  fontSize: 12.5,
                                  color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                                ),
                              ),
                            ],
                          ),
                        );
                      }

                      return Container(
                        padding: const EdgeInsets.all(14),
                        decoration: BoxDecoration(
                          color: isDark ? const Color(0xFF0F172A) : const Color(0xFFF8FAFC),
                          borderRadius: BorderRadius.circular(14),
                          border: Border.all(
                            color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
                          ),
                        ),
                        child: Row(
                          children: [
                            Container(
                              width: 44,
                              height: 44,
                              decoration: BoxDecoration(
                                color: primaryColor.withValues(alpha: 0.12),
                                shape: BoxShape.circle,
                              ),
                              child: Icon(
                                Icons.medical_services_outlined,
                                color: primaryColor,
                                size: 22,
                              ),
                            ),
                            const SizedBox(width: 14),
                            Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Row(
                                    children: [
                                      Flexible(
                                        child: Text(
                                          doctor.displayName,
                                          style: const TextStyle(
                                            fontSize: 16,
                                            fontWeight: FontWeight.w700,
                                          ),
                                        ),
                                      ),
                                      const SizedBox(width: 8),
                                      Container(
                                        padding: const EdgeInsets.symmetric(
                                          horizontal: 7,
                                          vertical: 2,
                                        ),
                                        decoration: BoxDecoration(
                                          color: const Color(0xFFE0F2FE),
                                          borderRadius: BorderRadius.circular(6),
                                        ),
                                        child: const Text(
                                          'VERIFIED',
                                          style: TextStyle(
                                            fontSize: 9.5,
                                            fontWeight: FontWeight.w700,
                                            color: Color(0xFF0284C7),
                                            letterSpacing: 0.5,
                                          ),
                                        ),
                                      ),
                                    ],
                                  ),
                                  const SizedBox(height: 3),
                                  Text(
                                    [doctor.specialty, doctor.clinic, doctor.district]
                                        .whereType<String>()
                                        .join(' · '),
                                    style: TextStyle(
                                      fontSize: 12,
                                      color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ],
                        ),
                      );
                    },
                  ),
            ],
          ),
        ),
        const SizedBox(height: 16),

        // 3. Find a Doctor Panel (Family Head only)
        if (widget.isHead) ...[
          Container(
            padding: const EdgeInsets.all(18),
            decoration: BoxDecoration(
              color: isDark ? const Color(0xFF1E293B) : Colors.white,
              borderRadius: BorderRadius.circular(18),
              border: Border.all(
                color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
              ),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withValues(alpha: isDark ? 0.3 : 0.03),
                  blurRadius: 12,
                  offset: const Offset(0, 4),
                ),
              ],
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Find a doctor',
                  style: TextStyle(
                    fontSize: 17.5,
                    fontWeight: FontWeight.w700,
                    color: isDark ? Colors.white : const Color(0xFF0F172A),
                  ),
                ),
                const SizedBox(height: 14),

                // Search inputs
                TextField(
                  controller: _searchController,
                  decoration: const InputDecoration(
                    labelText: 'Search',
                    hintText: 'Name or specialty',
                    prefixIcon: Icon(Icons.search, size: 20),
                  ),
                  onSubmitted: (_) => _onSearch(),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: _districtController,
                  decoration: const InputDecoration(
                    labelText: 'District',
                    hintText: 'e.g. Colombo',
                    prefixIcon: Icon(Icons.location_on_outlined, size: 20),
                  ),
                  onSubmitted: (_) => _onSearch(),
                ),
                const SizedBox(height: 12),
                ElevatedButton(
                  onPressed: _onSearch,
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF1D61E0),
                    foregroundColor: Colors.white,
                    minimumSize: const Size(double.infinity, 44),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  child: const Text('Search', style: TextStyle(fontWeight: FontWeight.w700)),
                ),
                const SizedBox(height: 16),

                // Search results
                ref.watch(doctorDirectoryProvider).when(
                      loading: () => const Padding(
                        padding: EdgeInsets.symmetric(vertical: 16),
                        child: Center(child: CircularProgressIndicator()),
                      ),
                      error: (_, _) => ErrorRetryView(
                        onRetry: () => ref.invalidate(doctorDirectoryProvider),
                      ),
                      data: (doctors) {
                        final districtFilter = ref.watch(doctorDistrictFilterProvider).toLowerCase();
                        final filteredDoctors = districtFilter.isEmpty
                            ? doctors
                            : doctors.where((d) => (d.district ?? '').toLowerCase().contains(districtFilter)).toList();

                        if (filteredDoctors.isEmpty) {
                          return Container(
                            padding: const EdgeInsets.all(16),
                            alignment: Alignment.center,
                            child: Text(
                              'No verified doctors found. Try a different name, specialty or district.',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                fontSize: 13,
                                color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                              ),
                            ),
                          );
                        }

                        return Column(
                          children: filteredDoctors.map((doctor) => _DoctorDirectoryRow(
                            doctor: doctor,
                            onRequest: () => widget.onRequest(
                              context,
                              ref,
                              widget.familyId,
                              doctor.id,
                              doctor.displayName,
                            ),
                          )).toList(),
                        );
